/*!
 * SplitText (GSAP-compatible line splitter & mask plugin)
 */
(function (global) {
  'use strict';

  function splitIntoLines(el, vars) {
    vars = vars || {};
    var originalHTML = el.innerHTML;
    var text = (el.textContent || '').trim().replace(/\s+/g, ' ');
    if (!text) {
      var emptyInst = { lines: [], words: [], chars: [], revert: function () { el.innerHTML = originalHTML; } };
      if (typeof vars.onSplit === 'function') vars.onSplit(emptyInst);
      return emptyInst;
    }

    var words = text.split(' ');
    el.innerHTML = '';
    var wordSpans = [];
    for (var i = 0; i < words.length; i++) {
      var ws = document.createElement('span');
      ws.style.display = 'inline-block';
      ws.textContent = words[i];
      el.appendChild(ws);
      wordSpans.push(ws);
      if (i < words.length - 1) {
        el.appendChild(document.createTextNode(' '));
      }
    }

    var lineGroups = [];
    var currentLine = [];
    var lastTop = null;

    for (var j = 0; j < wordSpans.length; j++) {
      var span = wordSpans[j];
      var top = span.offsetTop;
      if (lastTop === null || Math.abs(top - lastTop) <= 3) {
        currentLine.push(words[j]);
        if (lastTop === null) lastTop = top;
      } else {
        lineGroups.push(currentLine.join(' '));
        currentLine = [words[j]];
        lastTop = top;
      }
    }
    if (currentLine.length) {
      lineGroups.push(currentLine.join(' '));
    }

    el.innerHTML = '';
    var lines = [];
    var linesClass = vars.linesClass || 'split-line';
    var useMask = vars.mask === 'lines' || vars.mask === true;

    for (var k = 0; k < lineGroups.length; k++) {
      var lineEl = document.createElement('div');
      lineEl.className = linesClass;
      lineEl.style.display = 'block';
      lineEl.style.willChange = 'transform';
      lineEl.textContent = lineGroups[k];

      if (useMask) {
        var maskEl = document.createElement('div');
        maskEl.className = linesClass + '-mask';
        maskEl.style.display = 'block';
        maskEl.style.overflow = 'hidden';
        maskEl.appendChild(lineEl);
        el.appendChild(maskEl);
      } else {
        el.appendChild(lineEl);
      }
      lines.push(lineEl);
    }

    var instance = {
      lines: lines,
      words: [],
      chars: [],
      revert: function () {
        el.innerHTML = originalHTML;
      }
    };

    if (typeof vars.onSplit === 'function') {
      vars.onSplit(instance);
    }

    return instance;
  }

  function SplitText(target, vars) {
    var el = typeof target === 'string' ? document.querySelector(target) : target;
    if (!el) return { lines: [], revert: function () {} };
    return splitIntoLines(el, vars);
  }

  SplitText.version = '3.13.0';
  SplitText.register = function () {};
  SplitText.create = function (target, vars) {
    return new SplitText(target, vars);
  };

  global.SplitText = SplitText;
  if (global.gsap && typeof global.gsap.registerPlugin === 'function') {
    global.gsap.registerPlugin(SplitText);
  }
})(typeof window !== 'undefined' ? window : this);
